bool bipartiteCheckBfs_9(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> vis(V, 0); queue<int> q; for (int i = 0; i < V; ++i) { if (vis[i] != 0) continue; vis[i] = 1; q.push(i); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) { if (vis[v2] == 0) { vis[v2] = -vis[u]; q.push(v2); } else if (vis[v2] == vis[u]) return false; } } } return true; }
vector<int> kahnTopoSort_9(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> deg(V, 0); for (int u = 0; u < V; ++u) for (int v2 : adj[u]) ++deg[v2]; queue<int> q; for (int i = 0; i < V; ++i) if (deg[i] == 0) q.push(i); vector<int> order; while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v2 : adj[u]) if (--deg[v2] == 0) q.push(v2); } return order; }
